var a=`0294-tavce-gravce`;var i=`world-0294`;var n=`MK`;var o=`southern-europe`;var r=4;var s=854;var l={en:`Tavče Gravče`,ua:`Тавче гравче`};var u={en:`A traditional North Macedonia dish made with cannellini beans, yellow onion, garlic, tomato paste. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Північна Македонія. Основні інгредієнти: квасоля каннеліні, жовта цибуля, часник, томатна паста. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var g=[{en:`Cover the ingredients with cold water and soak for about 720 minutes; keep fish in the refrigerator, refreshing the water several times to remove excess salt. Drain before cooking.`,ua:`Залийте складники холодною водою і замочуйте приблизно 720 хвилин; рибу тримайте в холодильнику, кілька разів змінюючи воду для видалення зайвої солі. Перед готуванням злийте воду.`,t:[`soaking-legumes`],m:720,i:[[`cannellini-beans`,420,`g`],[`water`,1300,`ml`]]},{en:`Cook the listed ingredients in simmering water for about 90 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 90 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:90,i:[]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`yellow-onion`,170,`g`],[`garlic`,4,`clove`],[`extra-virgin-olive-oil`,45,`ml`],[`tomato-paste`,40,`g`],[`sweet-paprika`,6,`g`]]},{en:`Bake in a preheated 180°C oven for about 35 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 35 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:35,i:[[`bay-leaf`,2,`leaf`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]}];var d={slug:a,id:i,country:`MK`,region:o,servings:4,minutes:854,title:l,text:u,steps:g};export{n as country,d as default,i as id,s as minutes,o as region,r as servings,a as slug,g as steps,u as text,l as title};